-- Importación única de la planilla manual del CED ("Estado de Checklist_reclamo", hoja R1_2025) al registro de reclamos de conectividad.
-- Reglas: el FED se busca por su nombre de pila; la escuela, por el CUE del asunto (si existe en la base); estado "resuelto" si la planilla dice "sí" o la nota dice
-- "solucionado"; con número de ticket o incidencia, "en proceso"; sin número, "reclamo enviado". Lo que no es un número (ej.: "resulta la parte de PBA") va a las notas.
-- Es idempotente: no repite un reclamo de la planilla con el mismo asunto y fecha.
insert into public.reclamos_conectividad (fed_id, school_id, cue, tipo, tipo_label, conexion, asunto, enviado_at, estado, nro_incidencia, notas, origen)
select (select f.id from public.feds f where f.nombre_completo ilike v.fed || ' %' or f.nombre_completo ilike v.fed limit 1),
       (select e.id from public.establecimientos e where e.cue = v.cue::integer limit 1), v.cue::integer, 'planilla', v.tipo_label, v.conexion, v.asunto, v.enviado_at::timestamptz, v.estado, v.nro, v.notas, 'planilla'
